package com.saxonica.ee.elab.expr;

import com.saxonica.ee.elab.eval.PullEvaluator;
import com.saxonica.ee.elab.gen.Elaborator;
import com.saxonica.ee.elab.gen.PullElaborator;
import net.sf.saxon.expr.CardinalityChecker;
import net.sf.saxon.expr.Expression;

/**
 * Elaborator for a {@code treat as} expression, which is usually system-generated by
 * the type checking phase of the compiler
 */

public class CardinalityCheckerElaborator extends PullElaborator {

    @Override
    public PullEvaluator elaborateForPull() {
        CardinalityChecker exp = (CardinalityChecker) getExpression();
        Expression arg = exp.getBaseExpression();
        PullEvaluator argEval = Elaborator.makeElaborator(arg).elaborateForPull();

        return context -> exp.checkCardinality(argEval.eval(context), context);
    }

    // TODO: push-mode checking
}

